package cz.mh.rallye.rallye_backend.participation;
import java.time.*;import java.util.*;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.SimpleTransactionStatus;
import cz.mh.rallye.rallye_backend.participation.application.RegistrationService;
import cz.mh.rallye.rallye_backend.participation.persistence.RegistrationStore;
import cz.mh.rallye.rallye_backend.participation.persistence.RegistrationStore.*;
import cz.mh.rallye.rallye_backend.identity.application.*;import cz.mh.rallye.rallye_backend.identity.persistence.*;
import cz.mh.rallye.rallye_backend.crews.persistence.CrewStore;import cz.mh.rallye.rallye_backend.audit.application.AuditService;import cz.mh.rallye.rallye_backend.shared.persistence.CommandStore;
class RegistrationServiceTest {
 final RegistrationStore store=mock(RegistrationStore.class);final CrewStore crews=mock(CrewStore.class);final AccountStore accounts=mock(AccountStore.class);final AdminStore roles=mock(AdminStore.class);final CommandStore commands=mock(CommandStore.class);final AuditService audit=mock(AuditService.class);final PlatformTransactionManager manager=mock(PlatformTransactionManager.class);
 final Instant now=Instant.parse("2026-10-30T10:00:00Z");final UUID event=UUID.randomUUID(),crew=UUID.randomUUID(),id=UUID.randomUUID();final AuthService.Principal actor=new AuthService.Principal(UUID.randomUUID(),UUID.randomUUID(),false);RegistrationService service;
 Event e(String mode,Instant end,long version){return new Event(event,"Event",null,"PLANNED",now.plusSeconds(300),null,end,version,null,null,mode);}
 Row row(UUID captain,Instant started,long version){return new Row(id,event,crew,"Original","REGISTERED",version,now,now,"A\nB",1,started,started==null?null:captain,captain);}
 @BeforeEach void setup(){when(accounts.account(any())).thenAnswer(i->accounts.lockAccount(i.getArgument(0)));when(crews.read(any())).thenAnswer(i->crews.find(i.getArgument(0)));when(store.event(any(),eq(false))).thenAnswer(i->store.event(i.getArgument(0)));when(store.row(any(),any(),eq(false))).thenAnswer(i->store.lock(i.getArgument(0),i.getArgument(1)));service=new RegistrationService(store,crews,accounts,roles,commands,audit,Clock.fixed(now,ZoneOffset.UTC),manager);when(manager.getTransaction(any())).thenAnswer(i->new SimpleTransactionStatus());when(accounts.lockAccount(actor.accountId())).thenReturn(new AccountStore.Account(actor.accountId(),"synthetic@example.test","Captain","ACTIVE",null));when(roles.activeVerified(actor.accountId())).thenReturn(true);when(accounts.isActiveSession(any(),any(),any())).thenReturn(true);when(store.event(event)).thenReturn(e("AUTO",now.plusSeconds(3600),4));when(crews.find(crew)).thenReturn(new CrewStore.Crew(crew,actor.accountId(),"Current",null,null,null,null,null,null,null,now,now,2));when(store.crew(event,id)).thenReturn(crew);when(store.lock(event,id)).thenReturn(row(actor.accountId(),null,0));}
 @Test void scheduledPastStartClosesAutoWithoutMaterializing(){when(store.event(event)).thenReturn(new Event(event,"Event",null,"PLANNED",now.minusSeconds(300),null,now.plusSeconds(3600),4,null,null,"AUTO"));var result=service.status(actor,event);assertFalse(result.canRegister());assertFalse(result.canManageSettings());assertEquals(now.minusSeconds(300),result.event().startedAt());assertEquals("RUNNING",result.event().status());assertEquals("OFFICIAL_START_REACHED",result.reason());verify(store,never()).settings(any(),any(),any(),any(),any());}
 @Test void adminSettingsNoOpDoesNotTouchAuditOrVersion(){when(roles.administrator(actor.accountId())).thenReturn(true);var result=service.settings(actor,event,4,null,null,"AUTO");assertEquals(4,result.version());verify(store,never()).settings(any(),any(),any(),any(),any());verifyNoInteractions(audit);}
 @Test void settingsEnforceRoleVersionAndEnd(){assertEquals("ADMIN_REQUIRED",assertThrows(AuthFailure.class,()->service.settings(actor,event,4,null,null,"OPEN")).code());when(roles.administrator(actor.accountId())).thenReturn(true);assertEquals("RACE_EVENT_VERSION_CONFLICT",assertThrows(AuthFailure.class,()->service.settings(actor,event,3,null,null,"OPEN")).code());when(store.event(event)).thenReturn(e("AUTO",now,4));assertEquals("RACE_EVENT_ENDED",assertThrows(AuthFailure.class,()->service.settings(actor,event,4,null,null,"OPEN")).code());verifyNoInteractions(audit);}
 @Test void createStoresOnlyDigestAndIdsInLedger(){UUID key=UUID.randomUUID();var created=service.create(actor,event,key,crew,"Secret member\r\nB",1);assertEquals(0,created.version());verify(store).insert(eq(created.id()),eq(event),eq(crew),eq("Current"),eq("Secret member\nB"),eq(1),eq(now));verify(commands).save(eq(actor.accountId()),eq(key),eq(created.id()),eq("CREW_REGISTRATION_CREATE"),argThat(r->!r.contains("member")&&r.contains(event.toString())&&r.matches(".*[a-f0-9]{64}.*")),any(),eq(now));verify(audit).registration(actor.accountId(),AuditService.Event.REGISTRATION_CREATED,created.id(),event,0);}
 @Test void replayPrecedesClosedAndDuplicateChecksButNeverOwnership(){UUID key=UUID.randomUUID();when(store.event(event)).thenReturn(e("CLOSED",now,4));when(commands.replay(any(),eq(key),any(),any(),any())).thenReturn("{\"id\":\""+id+"\",\"version\":0}");assertEquals(id,service.create(actor,event,key,crew,"A",0).id());verify(store,never()).exists(any(),any());verify(store,never()).insert(any(),any(),any(),any(),any(),anyInt(),any());when(crews.find(crew)).thenReturn(null);assertEquals("CREW_NOT_FOUND",assertThrows(AuthFailure.class,()->service.create(actor,event,key,crew,"A",0)).code());verifyNoInteractions(audit);}
 @Test void newKeysRespectClosedAndDuplicate(){when(store.exists(event,crew)).thenReturn(true);assertEquals("CREW_ALREADY_REGISTERED",assertThrows(AuthFailure.class,()->service.create(actor,event,UUID.randomUUID(),crew,"A",0)).code());when(store.event(event)).thenReturn(e("CLOSED",null,4));assertEquals("REGISTRATION_CLOSED",assertThrows(AuthFailure.class,()->service.create(actor,event,UUID.randomUUID(),crew,"A",0)).code());}
 @Test void adminCanReadButCannotEditForeignRegistration(){UUID other=UUID.randomUUID();when(roles.administrator(actor.accountId())).thenReturn(true);when(crews.find(crew)).thenReturn(new CrewStore.Crew(crew,other,"Other",null,null,null,null,null,null,null,now,now,0));when(store.lock(event,id)).thenReturn(row(other,null,0));var detail=service.detail(actor,event,id);assertFalse(detail.compositionLocked());assertFalse(detail.canEditMembers());assertEquals("NOT_CAPTAIN",detail.editBlockedReason());assertEquals("REGISTRATION_NOT_FOUND",assertThrows(AuthFailure.class,()->service.members(actor,event,id,0,"X",0)).code());}
 @Test void closedRegistrationsDoNotLockUnstartedComposition(){when(store.event(event)).thenReturn(e("CLOSED",now.plusSeconds(3600),4));var result=service.members(actor,event,id,0,"A\r\nB",1);assertTrue(result.canEditMembers());verify(store,never()).members(any(),any(),anyInt(),any());verifyNoInteractions(audit);}
 @Test void membersChecksVersionBeforeEndAndStart(){when(store.event(event)).thenReturn(e("AUTO",now,4));assertEquals("REGISTRATION_VERSION_CONFLICT",assertThrows(AuthFailure.class,()->service.members(actor,event,id,1,"X",0)).code());assertEquals("RACE_EVENT_ENDED",assertThrows(AuthFailure.class,()->service.members(actor,event,id,0,"X",0)).code());when(store.event(event)).thenReturn(e("OPEN",null,4));when(store.lock(event,id)).thenReturn(row(actor.accountId(),now,1));assertEquals("REGISTRATION_VERSION_CONFLICT",assertThrows(AuthFailure.class,()->service.members(actor,event,id,0,"X",0)).code());assertEquals("REGISTRATION_COMPOSITION_LOCKED",assertThrows(AuthFailure.class,()->service.members(actor,event,id,1,"X",0)).code());verify(store,never()).members(any(),any(),anyInt(),any());verifyNoInteractions(audit);}
 @Test void listScopeAndPagingAreEnforced(){assertEquals(403,assertThrows(AuthFailure.class,()->service.list(actor,event,"all",0,50)).status());assertEquals(400,assertThrows(AuthFailure.class,()->service.list(actor,event,"mine",0,50)).status());assertEquals(400,assertThrows(AuthFailure.class,()->service.crews(actor,event,10001,50)).status());when(store.list(event,actor.accountId(),false,0,1)).thenReturn(List.of(row(actor.accountId(),null,0),row(actor.accountId(),null,0)));assertTrue(service.list(actor,event,"own",0,1).hasMore());}
 @Test void candidatesFallbackAndExistingRegistrationAreExplicit(){when(store.candidates(event,actor.accountId(),0,50)).thenReturn(List.of(new Candidate(crew,2,"Crew",actor.accountId(),null,null,null,null),new Candidate(UUID.randomUUID(),1,"Other own",actor.accountId(),id,id,"A\nB",1)));var list=service.crews(actor,event,0,50).items();assertEquals("Captain",list.getFirst().defaults().membersText());assertEquals("CAPTAIN_PROFILE",list.getFirst().defaults().source());assertTrue(list.getFirst().canRegister());assertEquals("ALREADY_REGISTERED",list.getLast().blockedReason());assertEquals("LAST_REGISTRATION",list.getLast().defaults().source());}
 @Test void failedAuditTriggersTransactionRollbackAndDoesNotReserveCommand(){doThrow(new IllegalStateException("Injected")).when(audit).registration(any(),any(),any(),any(),anyLong());assertThrows(IllegalStateException.class,()->service.create(actor,event,UUID.randomUUID(),crew,"A",0));verify(manager).rollback(any());verify(commands,never()).save(any(),any(),any(),any(),any(),any(),any());}

 @Test void ownListUsesOneBoundedReadAndCommonLifecycleProjection(){
  doReturn(new AccountStore.Account(actor.accountId(),"synthetic@example.test","Captain","ACTIVE",null)).when(accounts).account(actor.accountId());
  var first=new OwnRegistration(id,event,"Event",crew,"Current",now.minusSeconds(1),now.plusSeconds(100),"PLANNED",7);
  when(store.own(actor.accountId(),now,0,1)).thenReturn(List.of(first,first));
  var result=service.own(actor,0,1);assertTrue(result.hasMore());assertEquals(1,result.items().size());assertEquals("RUNNING",result.items().getFirst().raceEventStatus());assertEquals(7,result.items().getFirst().version());
  verify(store).own(actor.accountId(),now,0,1);verifyNoMoreInteractions(store);verifyNoInteractions(audit,commands,crews);verify(roles,never()).lock();verify(accounts,never()).lockAccount(any());
 }
 @Test void ownListEmptyAdminAndPagingNeverBroadenOwnership(){
  when(roles.administrator(actor.accountId())).thenReturn(true);when(store.own(actor.accountId(),now,0,100)).thenReturn(List.of());assertTrue(service.own(actor,0,100).items().isEmpty());
  for(int[] pair:List.of(new int[]{-1,50},new int[]{10001,50},new int[]{0,0},new int[]{0,101}))assertEquals(400,assertThrows(AuthFailure.class,()->service.own(actor,pair[0],pair[1])).status());
  assertEquals(401,assertThrows(AuthFailure.class,()->service.own(null,0,50)).status());verify(store).own(actor.accountId(),now,0,100);verifyNoMoreInteractions(store);
 }
}
